// Computes and returns the greatest common divisor of n and d
private static long gcd(long n, long d) {
  long n1 = Math.abs(n);
  long n2 = Math.abs(d);

  while (n2 != 0) {
    long rem = n1 % n2;
    n1 = n2;
    n2 = rem;
  }
  return n1;
}
